from naive.ecs import ExecutionCertificationSystemNaive
from protocol.storage.data_storage import DataStorage
from protocol.storage.file_system_storage import FileSystemStorage
from protocol.user.user_type import UserType
from protocol.utils.config_utils import load_config


class User:
    def __init__(self, user_type: UserType, ecs, run_args):
        self.user_type = user_type
        self.config = load_config("occp_naive.ini")
        self.storage_fs = FileSystemStorage()
        self.ecs: ExecutionCertificationSystemNaive = ecs
        self.storage_s3 = DataStorage(self.config["STORAGE"]["BucketName"])
        self.run_args = run_args
        self.logger = logging.getLogger(self.config["LOGGING"]["LogName"])

    def load_task_data(self):
        match self.user_type:
            case UserType.Normal:
                return (
                    self.storage_fs.load_source_code(self.run_args["key"]),
                    self.expected_results(),
                )
            case UserType.Malicious:
                return (
                    self.storage_fs.load_source_code(self.run_args["key"]),
                    "FAKE-RESULT",
                )
            case UserType.ERA:
                return (
                    self.storage_fs.load_source_code(self.run_args["alt_code"]),
                    self.expected_results(),
                )

