    def upload_task(self, task_data):
        start_time = time.time()
        task_id = self.ecs.add_task_seq(task_data)
        self.logger.info(f"--- {(time.time() - start_time)} seconds to upload task")
        return task_id

    def run(self):
        task_data = self.load_task_data()

        task_id = self.upload_task(task_data)
        return task_id

